import{_ as s,l,o as e,c as i,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"星型模式","description":"","frontmatter":{"title":"星型模式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/star-schema.md","filePath":"cs/star-schema.md","lastUpdated":1789023840000}'),h={name:"cs/star-schema.md"};function m(B,a,_,E,u,A){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="星型模式" tabindex="-1">星型模式 <a class="header-anchor" href="#星型模式" aria-label="Permalink to &quot;星型模式&quot;">​</a></h1><div class="epigraph"><p>事实表存度量与外键，维表存描述属性：分析查询沿键连维，是受控反规范化，不是忘了 3NF。</p><footer>—— 据 Kimball 维建模；Inmon 对照；5NF 反规范化课的分析落地</footer></div><p><a href="/cs/sqlite-architecture">上一课</a>收束嵌入式 OLTP。本课打开分析与流：数仓经典星型（star schema）。缺口是查询形状：<code>SUM</code> 按多个描述属性切。规范化 OLTP 要许多跳连接；星型把维退化成键，事实极窄、极长。雪花是维再规范化。OLAP 立方下一课预聚合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>度量（销售额）在事实；谁、何时、何地在维。缺口是<strong>键</strong>：代理键、退化维、缓慢变化维（SCD）类型——维上属性改了历史事实如何指。与 3NF：维常不满足 BCNF，这是读路径合同，写走 ETL 受控。</p><p>位图索引、列存在事实与低 NDV 维上极合适。分区按时间在事实表。</p><p><span class="marginnote">Kimball 维建模。Inmon 3NF 企业数仓是另一派，本课点名不站队。事实粒度量错会让所有合计不可加。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明粒度（一行订单行）。ETL 灌代理键。查询：事实 join 维，聚合。优化器：星型变换（先维过滤再探事实）是特殊改写，broadcast 维表。与 shuffle 课对接。</p><p>物化：常用汇总事实表，刷新合同即 MV 课。</p>',10)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E4%BA%8B%E5%AE%9E%3A%20%E9%94%AE%20%2B%20%E5%BA%A6%E9%87%8F%22%5D%20--%3E%20D1%5B%22%E7%BB%B4%22%5D%0A%20%20F%20--%3E%20D2%5B%22%E7%BB%B4%22%5D%0A%20%20FILT%5B%22%E7%BB%B4%E5%B1%9E%E6%80%A7%E8%BF%87%E6%BB%A4%22%5D%20--%3E%20BIT%5B%22%E4%BD%8D%E5%9B%BE%20%2F%20%E4%B8%8B%E6%8E%A8%22%5D%0A%20%20BIT%20--%3E%20F%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>计划：维小可广播。无事实表分区裁剪则扫全部历史。HTAP：OLTP 3NF 与星型副本 CDC。文档反规范订单是另一种星（嵌套维）。</p><p>校准：列存扫事实。学习优化器对星型连接顺序有偏见搜索。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 cube 操作符。也不把星型当事务模式。湖仓可用星型逻辑、Parquet 物理。</p><p>后课默认：分析模型先定粒度再星型。OLAP 立方：预先 rollup 的格，查询切块。</p><p>粒度错了，再快的列存也加错数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>星型：窄事实+宽维，受控反规范服务聚合查询。</li><li>星型变换与广播维表是计划特化。</li><li>OLAP 立方下一课。</li><li>出处：Kimball；Inmon 对照；反规范化课。</li></ul>',9))])}const P=s(h,[["render",m]]);export{f as __pageData,P as default};
